{
 "research_concepts": [
  "offensive reorganization",
  "points per possession",
  "player absence impact",
  "play-type distribution analysis",
  "baseline comparison for offensive metrics"
 ],
 "methodological_questions": [
  "quantifying offensive reorganization",
  "defining baseline 'L' for player absence studies",
  "measuring change in team efficiency",
  "confounding factors in player absence studies",
  "unit of analysis for player absence spells"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence. Usage-matched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25."
  },
  {
   "id": "FAM:SF20",
   "status_as_recorded": "untestable",
   "finding": "Real player absences move the association structure (V1) and the LOO simulation predicts the magnitude (V2). V1(a) 16/23 above p95, binomial p=2.67e-16; V1(b) mean(D_real - median_null)=+0.142, CI [+0.103, +0.187] CONFIRMED. V2a Spearman +0.288, p=0.077, CI [-0.244, +0.667] FAIL; V2b partial +0.253, p=0.115, CI [-0.262, +0.615] FAIL."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "Having a similar-profile teammate separates absorption from cascade when a player sits. Result: mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Similarity does not separate absorption from cascade; almost always findable."
  },
  {
   "id": "FAM:SF-APPA-017",
   "status_as_recorded": "rejected",
   "finding": "Routing possessions to each play type's best player adds value over A3, and survives defensive attention adaptation. Result: V4 A5 vs A3 +0.77; V5 +0.94 (A5b vs A5 +0.01); V6 (520 matchups) A5 vs A3 +0.03, A5b vs A5 -0.00. Shrinks from +0.94 to +0.03 pts/100 on the larger 520-matchup sample."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "An action gets less effective the more often the defense has already seen it in the game. Result: League-wide within-game -0.0019 PPP/exposure (SE 0.0019); across-game +0.0004 (SE 0.0015); H1 exposures to H2 -0.0000 (SE 0.0024). After 5 exposures, effects >~0.02 ruled out. Only PULL_UP within-game -0.030 SE (survives Holm)."
  },
  {
   "id": "FAM:SF-CHT-063",
   "status_as_recorded": "artifact",
   "finding": "The BEST-vs-continue gap after a slump is evidence of costly failure to abandon a suppressed play (depends on the slump event). Result: After event BEST 1.403 vs continue 1.154, gap +0.248 (SE 0.009). No-slump events +0.239 vs +0.248. League-wide ranking no game info +0.238. Gap is the same without a slump (+0.239) and with a fixed CUT-heavy ranking (+0.238)."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Describe how play-type mix shifts by halftime margin, crunch time and after runs. Result: OTHER +2.26 to +2.48pp in H2 in every bucket; crunch OTHER +6.08pp, PULL_UP +1.20pp at -0.045 PPP; post-run DRIVE +3.75pp, OTHER -6.72pp."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). Result: FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0."
  },
  {
   "id": "FAM:SF-APPS-071",
   "status_as_recorded": "not a hypothesis test",
   "finding": "A memoryless state-driven process calibrated to NBA micro-stats can match uncalibrated distributional targets (esp. lag-1 scoring autocorr). Result: Uncalibrated: PPP std 1.149 vs sim 1.152; lag-1 scoring autocorr real -0.0022 vs sim +0.0029; share 0 pts 0.475 vs 0.484. Sequence-only R2=0.00000; state-only 0.00002."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily. Result: Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF20",
   "what_failed": "Prediction of magnitude of structural movement due to absence using LOO simulation (V2a, V2b)",
   "why": "LIM:small_sample; failed to find significant correlation."
  },
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using similar-profile teammate to separate absorption from cascade",
   "why": "B_powered_null (adequately powered null result); LIM:label_or_classification_error; Similarity does not separate absorption from cascade."
  },
  {
   "id": "FAM:SF-APPA-017",
   "what_failed": "Routing possessions to each play type's best player for added value (A5 vs A3, A5b vs A5)",
   "why": "B_powered_null (adequately powered null result); Effect shrinks from +0.94 to +0.03 pts/100 on the larger 520-matchup sample, indicating initial findings were likely noise or artifact."
  },
  {
   "id": "FAM:SF38",
   "what_failed": "General hypothesis of action getting less effective with exposure",
   "why": "LIM:insufficient_exposure, LIM:label_or_classification_error, LIM:low_measurement_reliability; only one specific play type (PULL_UP) showed a significant effect."
  },
  {
   "id": "FAM:SF-CHT-063",
   "what_failed": "Identifying a BEST-vs-continue gap as slump-dependent evidence of costly failure",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); Gap is the same without a slump and with a fixed CUT-heavy ranking, indicating it's an artifact of the calculation."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Demonstrating decaying cross-possession memory for play-type actions",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); Flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferred labels for defensive scheme change to separate real adjustment from offensive execution",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  }
 ],
 "evidence_establishes": [
  "Offensive identity (FAM:SF-APPS-088) and association structure (FAM:SF20) do reorganize/displace significantly in response to player absences, especially for key 'connector' players. This confirms that the independent variable ('how much the offense reorganizes') is measurable and responsive to real-world events.",
  "Play-type mix shifts in response to within-game tactical situations (halftime, crunch time, post-run), demonstrating that offensive reorganization is an observable phenomenon beyond just player absence (FAM:SF-APPM-021).",
  "Measuring changes in offensive value (e.g., points per possession) and attributing them to specific offensive adjustments is challenging and prone to artifacts or null results (FAM:SF-APPA-017, FAM:SF-CHT-063, FAM:SF-CHT-029).",
  "Defensive adaptation is a significant factor affecting play effectiveness (FAM:SF38) and can confound studies of offensive changes, and inferred defensive scheme changes are difficult to validate (FAM:SF-APPA-005)."
 ],
 "evidence_does_not_establish": [
  "How to reliably and robustly quantify 'offensive reorganization' in a way that is predictive of changes in points per possession. While reorganization is shown to occur, the specific metric for 'how much' is not established as predictive of PPP.",
  "A clear methodology for defining the 'L' (baseline) in a way that isolates the effect of reorganization from other confounding factors.",
  "Whether the magnitude of offensive reorganization, once quantified, has a predictable and significant relationship with changes in points per possession.",
  "The specific mechanisms (e.g., absorption vs. cascade) that drive offensive reorganization and how they relate to offensive efficiency, as 'similarity' did not distinguish these (FAM:SF-CHT-052).",
  "The reliability of play-type labels, especially 'OTHER', which can impact the accuracy of reorganization measurements (FAM:SF-APPM-021, FAM:SF38)."
 ],
 "own_inferences": [
  "The research question is testable in principle, as both offensive reorganization and points per possession are measurable. The challenge lies in defining and measuring 'reorganization' robustly and isolating its predictive power on PPP changes from confounding factors.",
  "The 'relative to L' component implies a need for a robust baseline, likely a 'leave-one-out' (LOO) or 'player-on/player-off' comparison to establish counterfactual play-type distributions and PPP.",
  "The existing data, particularly derived play-type possession records, is suitable for quantifying offensive reorganization and points per possession.",
  "The unit of analysis will likely be player absence spells, comparing team offensive characteristics and PPP with and without the absent player, relative to the established baseline."
 ],
 "uncertainties": [
  "The precise definition and robust measurement of 'how much the offense reorganizes' is not explicitly defined in the question or fully established by historical evidence as a predictive metric for PPP.",
  "The specific methodology for establishing 'L' (baseline) to control for team strength, opponent strength, and other game-state variables for each absence spell is not detailed.",
  "The extent of confounding from defensive adaptation (FAM:SF38, FAM:SF-APPA-005) or other in-game tactical adjustments (FAM:SF-APPM-021) on the observed change in points per possession is a significant unknown.",
  "The reliability and consistency of play-type labels (FAM:SF-APPM-021, FAM:SF-CHT-052) could impact the accuracy of measuring offensive reorganization."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly supports that offensive reorganization occurs due to player absence and is measurable (FAM:SF-APPS-088, FAM:SF20). This increases confidence in the testability of the independent variable. However, it also highlights significant challenges in linking offensive changes to offensive value, with previous attempts yielding null or artifactual results (FAM:SF-APPA-017, FAM:SF-CHT-063, FAM:SF-CHT-029). The evidence also emphasizes confounding factors like defensive adaptation (FAM:SF38) and issues with label reliability (FAM:SF-APPM-021, FAM:SF-CHT-052, FAM:SF-APPA-005). This shifts the decision from a straightforward 'proceed' to 'proceed_with_changes' to explicitly address these methodological risks and refine the design to account for these past failures and limitations."
 },
 "testability": {
  "p_testable": 0.7,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-APPS-088",
   "FAM:SF20"
  ],
  "summary": "Previous work established that offensive identity and association structure reorganize significantly in response to player absences (FAM:SF-APPS-088, FAM:SF20). However, the specific question of whether the *magnitude* of this reorganization predicts the change in points per possession has not been directly answered. Attempts to predict value from offensive routing (FAM:SF-APPA-017) or attribute effects to tactical changes (FAM:SF-CHT-063, FAM:SF-CHT-029) have often yielded null, inconclusive, or artifactual results, highlighting the difficulty of this type of causal inference. Defensive adaptation (FAM:SF38) and label reliability (FAM:SF-APPM-021) are known confounders and limitations."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Change in points per possession can be influenced by many factors beyond offensive reorganization, such as opponent defense, game state, other player absences/returns, and general team performance trends. Isolating the effect of reorganization requires careful control."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Quantifying 'how much the offense reorganizes' will rely on derived play-type data. The reliability of these play-type labels, especially 'OTHER', has been questioned (FAM:SF-APPM-021), potentially introducing noise into the independent variable."
  },
  {
   "code": "LABEL_ERROR",
   "text": "Errors or inconsistencies in play-type classification could directly affect the measurement of offensive reorganization (FAM:SF-CHT-052, FAM:SF38, FAM:SF-APPM-021, FAM:SF-APPA-005), leading to inaccurate assessment of the independent variable."
  },
  {
   "code": "RTM_SELECTION",
   "text": "Player absences are not random. High-impact players might be absent due to injury or rest, which could correlate with other factors affecting team performance (e.g., team morale, opponent strength chosen for rest). Regression to the mean could also be a factor if absences occur during periods of unusual performance."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While n=148 spells and n=986 overall units are available, previous studies on player absence and offensive identity have been limited by small sample sizes (FAM:SF-APPS-088, FAM:SF20), especially for specific player roles or types of reorganization. Achieving sufficient power to detect a nuanced predictive relationship might be challenging."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "Measures of offensive reorganization or efficiency might encounter mechanical floors or ceilings, limiting the observable range of effect (FAM:SF-APPS-088, FAM:SF-APPS-071)."
  }
 ],
 "predicted_outcome": {
  "supported": 0.3,
  "rejected": 0.3,
  "untestable": 0.1,
  "artifact": 0.1,
  "uncertain": 0.2
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of the magnitude of offensive reorganization, defined as the Euclidean distance (or similar metric) between the baseline (L) and post-absence play-type distribution, on the change in points per possession (PPP) during player absence spells, after controlling for confounding factors.",
  "unit": "Player absence spell. An absence spell is defined as a contiguous set of games where a specific player (or set of players) is absent, compared to a baseline period where they were present.",
  "sample": "NBA 2022-23 to 2025-26 regular season and playoffs. Selection criteria: Player absence spells for key rotational players (e.g., top 8 usage players per team) with a minimum duration (e.g., 3+ games) to allow for observation of reorganization. Exclude spells where multiple key players are absent simultaneously to simplify attribution. Filter for spells with sufficient pre-absence data to establish a stable baseline 'L'. The given N=148 spells will be the primary unit of analysis.",
  "power": "The stated N=148 spells for rho correlation suggests a moderate power. A minimum detectable effect size (MDE) for a correlation coefficient (rho) should be explicitly calculated. If the MDE is too large for meaningful detection, the study may be underpowered for subtle effects. Power analysis will be conducted to determine the minimum detectable effect size for the correlation, given n=148 spells.",
  "controls": "Match each absence spell with a 'control' period for the same team or comparable team where the player was present, or use a difference-in-differences approach. Control for: opponent strength, game pace, season effects, home/away, score margin, and other simultaneously absent players. Use a fixed-effects model for teams and players to account for unobserved heterogeneity. The baseline 'L' for play-type distribution and PPP will be established from the player's 'on-court' possessions in a pre-absence window (e.g., 10-15 games prior) or through a leave-one-out (LOO) simulation if a robust LOO model is available and validated.",
  "falsification": "A falsification test could involve analyzing whether 'reorganization' metrics derived from random permutations of play-type distributions (not tied to actual absences) show a similar predictive relationship with PPP changes. Another falsification could be to test if reorganization predicts PPP in scenarios where it is mechanically impossible or known not to have an effect (e.g., very short, low-usage player absences).",
  "multiplicity": "Given a single primary estimand (correlation between reorganization and PPP change), standard p-value correction for multiple comparisons will not be necessary. If multiple definitions of 'reorganization' or multiple outcome metrics are explored, adjust p-values (e.g., Bonferroni, Holm-Bonferroni) for each family of tests.",
  "decision_rule": "The hypothesis will be supported if a statistically significant (p < 0.05) and practically meaningful positive correlation (rho > X, where X is a pre-specified threshold based on domain knowledge) is observed between the magnitude of offensive reorganization and the change in points per possession, after controlling for confounders. The null hypothesis is that there is no such predictive relationship.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs, and 2025-26 regular season (complete from 2026-04-13) and playoffs (complete from 2026-06-21) data, using the derived play-type possession records."
 }

